    "sourceHash": "d451d89c9bce7f9612037fe209da96d432c9fb0531c85abc5909af5e05dd2174",
    "sourcePath": "data/alice-corpus/examples/alice-local-encryption.fr.md",
    "theme": "Alice App et apprentissage"
