    "sourceHash": "9d7dbdb5a2cdce20afd42a264b8885a65301989a560e8fefe95d401fd5ca11fd",
    "sourcePath": "data/alice-corpus/examples/secondary-privacy-single-sign-on-risk.en.md",
    "theme": "privacy"
